import * as T from './vendor/three.js';
import {WIDTH,DEPTH,XROAD,ZROAD,districts,typeColors} from './city.js';
import {avatarCanvas} from './avatars.js';
export function createWorld(container,sim){const scene=new T.Scene();scene.background=new T.Color('#addae7');scene.fog=new T.FogExp2('#addae7',.0014);const camera=new T.PerspectiveCamera(42,innerWidth/innerHeight,.1,600);const renderer=new T.WebGLRenderer({antialias:true});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.25));renderer.shadowMap.enabled=false;renderer.shadowMap.type=T.PCFSoftShadowMap;container.append(renderer.domElement);const hemi=new T.HemisphereLight('#fff5dc','#699679',2.3);scene.add(hemi);const sun=new T.DirectionalLight('#fff2d0',2.5);sun.position.set(-60,100,30);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-110,right:110,top:90,bottom:-90});sun.shadow.bias=-.001;scene.add(sun);
const mats={};const mat=color=>mats[color]??=new T.MeshStandardMaterial({color,roughness:.85});const cube=new T.BoxGeometry(1,1,1),cone=new T.ConeGeometry(1,1,4),sphere=new T.IcosahedronGeometry(1,1);
function box(x,y,z,w,h,d,color,parent=scene){const m=new T.Mesh(cube,mat(color));m.position.set(x,y,z);m.scale.set(w,h,d);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function tree(x,z,s=1,parent=scene){box(x,.7*s,z,.3*s,1.4*s,.3*s,'#967353',parent);const m=new T.Mesh(sphere,mat('#57a66d'));m.position.set(x,2*s,z);m.scale.set(1.15*s,1.5*s,1.15*s);m.castShadow=true;parent.add(m)}
box(0,-1.2,0,WIDTH,2,DEPTH,'#609784');box(0,-.12,0,WIDTH-1,.3,DEPTH-1,'#93c978');box(WIDTH/2-5,.02,0,7,.18,DEPTH-1,'#55bad6');
for(let x=-XROAD;x<=XROAD;x+=20){box(x,.08,0,5,.2,ZROAD*2+6,'#d8cba2');box(x-2.3,.2,0,.6,.08,ZROAD*2+6,'#f6e7c1');box(x+2.3,.2,0,.6,.08,ZROAD*2+6,'#f6e7c1');for(let z=-ZROAD;z<=ZROAD;z+=5)box(x,.2,z,.09,.02,1.5,'#fff2cf')}
for(let z=-ZROAD;z<=ZROAD;z+=20){box(0,.09,z,XROAD*2+6,.2,5,'#d8cba2');box(0,.2,z-2.3,XROAD*2+6,.08,.6,'#f6e7c1');box(0,.2,z+2.3,XROAD*2+6,.08,.6,'#f6e7c1');for(let x=-XROAD;x<=XROAD;x+=5)box(x,.21,z,1.5,.02,.09,'#fff2cf')}
for(let x=-WIDTH/2+6;x<WIDTH/2-9;x+=8){tree(x,-DEPTH/2+5,.9);tree(x,DEPTH/2-5,1.1)}
const parcelGroups=new Map();function renderParcel(p){let old=parcelGroups.get(p.id);if(old)scene.remove(old);const g=new T.Group();scene.add(g);parcelGroups.set(p.id,g);box(p.x,.12,p.z,14,.18,14,p.type==='empty'?'#a0cf7a':'#a8ce8a',g);box(p.x,.22,p.z+7,12,.12,2,'#e6deb7',g);
if(['empty','park','forest','pond'].includes(p.type)){if(p.type==='park'){box(p.x,.23,p.z,2,.12,12,'#e8d5a1',g);box(p.x,.24,p.z,12,.12,2,'#e8d5a1',g);box(p.x-3,.6,p.z+3,2,.3,.7,'#a97f64',g);box(p.x+3,.6,p.z-3,2,.3,.7,'#a97f64',g)}if(p.type==='pond')box(p.x,.25,p.z,9,.2,8,'#6ac6d4',g);if(p.type!=='empty')for(let i=0;i<(p.type==='forest'?9:4);i++)tree(p.x-5+(i*7)%11,p.z-5+(i*3)%11,.8+i%3*.15,g);return}
if(p.type==='farm'){for(let j=0;j<6;j++){box(p.x-5+j*1.8,.3,p.z,1,.25,9,'#9f8054',g);for(let k=0;k<5;k++)box(p.x-5+j*1.8,.65,p.z-4+k*2,.7,.5,.6,j%2?'#a9c64f':'#70ab5b',g)}return}
const h=p.type==='home'?3.4+(p.id%3)*1.4:p.type==='work'?6:4.3;box(p.x,h/2,p.z,7,h,7,typeColors[p.type],g);if(p.type==='home'||p.type==='market'){const roof=new T.Mesh(cone,mat(p.type==='market'?'#eead5f':['#d87574','#798ece','#6caaa4'][p.id%3]));roof.position.set(p.x,h+1.4,p.z);roof.scale.set(5.6,2.8,5.6);roof.rotation.y=Math.PI/4;roof.castShadow=true;g.add(roof)}else box(p.x,h+.2,p.z,7.6,.4,7.6,'#678ea4',g);
for(let y=1.5;y<h;y+=1.8)for(let x=-2;x<=2;x+=2){box(p.x+x,y,p.z+3.55,.9,.9,.06,'#fff1b4',g);box(p.x+3.55,y,p.z+x,.06,.9,.9,'#cde4ed',g)}box(p.x,.85,p.z+3.55,1.3,1.7,.08,'#496882',g);if(p.type==='clinic'){box(p.x,3.2,p.z+3.62,2,.55,.1,'#fff9e5',g);box(p.x,3.2,p.z+3.63,.55,2,.1,'#fff9e5',g)}if(p.type==='market')for(let i=0;i<5;i++)box(p.x-3+i*1.5,2.5,p.z+4.5,1.45,.2,2,i%2?'#fff1b8':'#ef8c7d',g);tree(p.x-5,p.z-5,.85,g);tree(p.x+5,p.z+3,.65,g)}
let revision=-1;const editGroup=new T.Group();scene.add(editGroup);function rebuild(world){for(const p of world.parcels)renderParcel(p);editGroup.clear();for(const k of world.closed){const [x,z]=k.split(',').map(Number);box(x,.8,z,4,.4,.5,'#e1766c',editGroup);box(x-1.5,.4,z,.2,.8,.3,'#425777',editGroup);box(x+1.5,.4,z,.2,.8,.3,'#425777',editGroup)}for(const h of world.hazards){const m=new T.Mesh(new T.RingGeometry(h.radius-.3,h.radius,48),new T.MeshBasicMaterial({color:'#e87373',side:T.DoubleSide,transparent:true,opacity:.5}));m.rotation.x=-Math.PI/2;m.position.set(h.x,.3,h.z);editGroup.add(m)}revision=world.revision}
const meshes=new Map(),ring=new T.Mesh(new T.RingGeometry(.85,1.05,24),new T.MeshBasicMaterial({color:'#ffe582',side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;scene.add(ring);const routeLine=new T.Line(new T.BufferGeometry(),new T.LineBasicMaterial({color:'#ffe8a3',transparent:true,opacity:.85}));scene.add(routeLine);
const ghost=box(0,.4,0,14,.15,14,'#fff2a3');ghost.material=new T.MeshBasicMaterial({color:'#ffe39c',transparent:true,opacity:.4});ghost.visible=false;
const playerModel=new T.Group();scene.add(playerModel);playerModel.visible=false;
box(0,1.2,0,.85,1,.55,'#ffca61',playerModel);box(0,2,0,.68,.68,.65,'#db9b70',playerModel);box(0,2.35,0,.75,.18,.7,'#35465c',playerModel);box(-.52,1.15,0,.22,.9,.3,'#db9b70',playerModel);box(.52,1.15,0,.22,.9,.3,'#db9b70',playerModel);const playerLegs=[box(-.23,.42,0,.3,.8,.35,'#395b76',playerModel),box(.23,.42,0,.3,.8,.35,'#395b76',playerModel)];box(-.18,2.03,.34,.08,.08,.03,'#243346',playerModel);box(.18,2.03,.34,.08,.08,.03,'#243346',playerModel);
const playerHalo=new T.Mesh(new T.RingGeometry(.75,.9,32),new T.MeshBasicMaterial({color:'#ffe585',side:T.DoubleSide}));playerHalo.rotation.x=-Math.PI/2;playerHalo.position.y=.05;playerModel.add(playerHalo);
const cars=[];for(let i=0;i<14;i++){const g=new T.Group();box(0,.6,0,1.8,.9,3,['#ed997c','#6da3ce','#eee4b2','#bfa2d4'][i%4],g);box(0,1.2,0,1.6,.6,1.5,'#c3e1e6',g);scene.add(g);cars.push(g)}
const rainGeo=new T.BufferGeometry(),rainArr=new Float32Array(600*3);for(let i=0;i<600;i++){rainArr[i*3]=(i*13.17%190)-95;rainArr[i*3+1]=i%25;rainArr[i*3+2]=(i*7.37%140)-70}rainGeo.setAttribute('position',new T.BufferAttribute(rainArr,3));const rain=new T.Points(rainGeo,new T.PointsMaterial({color:'#d6f3ff',size:.22,transparent:true,opacity:.75}));scene.add(rain);
let nowPhase=0;function update(sim,selected,dt,time){if(revision!==sim.world.revision)rebuild(sim.world);for(const c of sim.citizens){if(!meshes.has(c.id)){const texture=new T.CanvasTexture(avatarCanvas(c.id));texture.magFilter=T.NearestFilter;texture.minFilter=T.NearestFilter;texture.colorSpace=T.SRGBColorSpace;const m=new T.Sprite(new T.SpriteMaterial({map:texture,alphaTest:.1,depthTest:false}));m.userData.id=c.id;m.scale.set(2.4,3,1);m.position.set(c.x,1.5,c.z);scene.add(m);meshes.set(c.id,m)}const m=meshes.get(c.id);m.position.x+=(c.x-m.position.x)*Math.min(1,dt*18);m.position.z+=(c.z-m.position.z)*Math.min(1,dt*18);m.position.y=1.5+(c.phase==='Traveling'?Math.sin(time*.009+c.id)*.1:0);const s=c.age<18?.72:1;m.scale.set(2.4*s,3*s,1)}for(const [id,m]of meshes)if(!sim.citizens.some(c=>c.id===id)){scene.remove(m);m.material.map.dispose();m.material.dispose();meshes.delete(id)}const c=sim.citizens.find(c=>c.id===selected);ring.visible=!!c;if(c){ring.position.set(c.x,.3,c.z);routeLine.geometry.dispose();routeLine.geometry=new T.BufferGeometry().setFromPoints([{x:c.x,z:c.z},...c.route].map(p=>new T.Vector3(p.x,.28,p.z)))}routeLine.visible=!!c;
const night=sim.light==='Night'||(sim.light==='Cycle'&&(sim.day%1<.25||sim.day%1>.8));sun.intensity=night?.3:sim.weather==='Storm'?.8:2.5;hemi.intensity=night?.8:2.3;scene.background.set(night?'#344a70':sim.weather==='Storm'?'#829dad':'#addae7');scene.fog.color.copy(scene.background);rain.visible=['Rain','Storm'].includes(sim.weather);if(rain.visible){for(let i=0;i<600;i++){rainArr[i*3+1]-=dt*15;if(rainArr[i*3+1]<.2)rainArr[i*3+1]=25}rainGeo.attributes.position.needsUpdate=true}nowPhase+=dt;cars.forEach((m,i)=>{const z=(i*40+nowPhase*5)%(ZROAD*2)-ZROAD,x=-XROAD+(i%13)*20;const blocked=sim.world.closed.includes(`${x},${Math.round(z/20)*20}`);m.visible=!blocked;m.position.set(x+1,.2,z)});}
return {scene,camera,renderer,meshes,ghost,update,updatePlayer(p,active,moving,time){playerModel.visible=active;if(!active)return;playerModel.position.set(p.x,.2,p.z);playerModel.rotation.y=p.heading;playerLegs.forEach((leg,i)=>leg.rotation.x=moving?Math.sin(time*.012+i*Math.PI)*.5:0);},resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)},pick(e){const ray=new T.Raycaster();ray.setFromCamera(new T.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),camera);return ray.intersectObjects([...meshes.values()])[0]?.object.userData.id},ground(e){const ray=new T.Raycaster();ray.setFromCamera(new T.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),camera);return ray.ray.intersectPlane(new T.Plane(new T.Vector3(0,1,0),0),new T.Vector3())}}}
